package fraymus.workspace;
import org.json.*;
import java.util.*;

/** Post-recording verification. Reference positions must be independently supplied, never predictions. */
final class TabletopAnalysis {
    static JSONObject compute(JSONObject run,JSONObject input,JSONObject profile){
        String kind=input.getString("kind");var trace=run.getJSONArray("trace");if(!run.getString("status").equals("completed")||trace.length()<12)throw new IllegalStateException("Analysis requires a completed recording with at least12 post-seed frames");var out=new JSONObject().put("kind",kind).put("runId",run.getString("id")).put("geometrySha256",run.getJSONObject("geometry").getString("sha256")).put("codeSha256",run.getString("codeSha256")).put("bodyId",run.getString("bodyId")).put("worldId",run.getJSONObject("nativeBinding").getString("worldId"));
        if(kind.equals("stationarity")){
            double mx=0,my=0;int n=0;for(Object raw:trace){var e=((JSONObject)raw).getJSONObject("estimate");if(e.getBoolean("accepted")){n++;mx+=e.getJSONArray("positionM").getDouble(0);my+=e.getJSONArray("positionM").getDouble(1);}}if(n<12)throw new IllegalStateException("Not enough actual accepted measurements for stability");mx/=n;my/=n;double square=0;for(Object raw:trace){var e=((JSONObject)raw).getJSONObject("estimate");if(e.getBoolean("accepted"))square+=Math.pow(e.getJSONArray("positionM").getDouble(0)-mx,2)+Math.pow(e.getJSONArray("positionM").getDouble(1)-my,2);}double rms=Math.sqrt(square/n);return out.put("metrics",new JSONObject().put("accepted",n).put("frames",trace.length()).put("jitterRmsM",rms).put("toleranceM",.003)).put("passed",n==trace.length()&&rms<=.003).put("qualification","Human-declared static window; jitter about its mean, not absolute accuracy. Subpixel-search resolution and3mm anchor budget limit physical claims.");
        }
        if(kind.equals("displacement")){
            if(trace.length()<16)throw new IllegalStateException("At least eight start and eight end samples required");double[] first=mean(trace,0,8),last=mean(trace,trace.length()-8,trace.length());var plane=new PlaneCalibration(run.getJSONObject("geometry").getJSONObject("definition"));var check=run.getJSONObject("check");double[] a=PlaneCalibration.point(check.getJSONArray("pointA")),b=PlaneCalibration.point(check.getJSONArray("pointB"));a=plane.project(a[0],a[1]);b=plane.project(b[0],b[1]);double markDelta=input.getDouble("toMark")-input.getDouble("fromMark");PlaneCalibration.bounded(markDelta,-12,12);if(Math.abs(markDelta)<.5)throw new IllegalArgumentException("Declare at least half an inch/cm of physical movement");double f=markDelta/(check.getDouble("markB")-check.getDouble("markA"));double[] expected={(b[0]-a[0])*f,(b[1]-a[1])*f};double expectedLength=Math.abs(markDelta)*switch(check.getString("unit")){case "in"->.0254;case "cm"->.01;default->1;};double norm=Math.hypot(expected[0],expected[1]);expected[0]*=expectedLength/norm;expected[1]*=expectedLength/norm;double[] actual={last[0]-first[0],last[1]-first[1]};double error=PlaneCalibration.distance(actual,expected);return out.put("fromMark",input.getDouble("fromMark")).put("toMark",input.getDouble("toMark")).put("unit",check.getString("unit")).put("metrics",new JSONObject().put("firstMeanM",new JSONArray(first)).put("lastMeanM",new JSONArray(last)).put("expectedDeltaM",new JSONArray(expected)).put("actualDeltaM",new JSONArray(actual)).put("vectorErrorM",error).put("toleranceM",.010)).put("passed",error<=.010).put("qualification","Human-declared same target alignment/parallel movement at start/end. First/last eight frames must all be measured; no predicted samples or selected favourable windows.");
        }
        if(!Set.of("fit","evaluate").contains(kind))throw new IllegalArgumentException("Unknown tabletop analysis");
        var refs=input.getJSONArray("references");if(refs.length()<12||refs.length()>96)throw new IllegalArgumentException("Provide12..96 independent later reference positions");var scores=new JSONArray();var seen=new HashSet<Integer>();var ratios=new ArrayList<Double>();int covered=0;double radiusSum=0,errorSum=0;
        if(kind.equals("evaluate")){if(profile==null||!profile.getString("kind").equals("fit")||profile.getString("runId").equals(run.getString("id"))||!profile.getString("geometrySha256").equals(out.getString("geometrySha256"))||!profile.getString("codeSha256").equals(out.getString("codeSha256"))||!profile.getString("bodyId").equals(out.getString("bodyId"))||!profile.getString("worldId").equals(out.getString("worldId")))throw new IllegalArgumentException("Use a different completed run with the same target/world/geometry/runtime");}
        for(Object raw:refs){var ref=(JSONObject)raw;SpatialScene.keys(ref,"ordinal","positionM");int ordinal=ref.getInt("ordinal");if(ordinal<1||ordinal>trace.length()||ordinal!=ref.getDouble("ordinal")||!seen.add(ordinal))throw new IllegalArgumentException("Distinct source ordinals, seed excluded");double[] truth=PlaneCalibration.point(ref.getJSONArray("positionM"));var e=trace.getJSONObject(ordinal-1).getJSONObject("estimate");if(kind.equals("fit")&&!e.getBoolean("accepted"))throw new IllegalStateException("Uncertainty fitting requires real accepted measurements, not lost/predicted positions");double err=PlaneCalibration.distance(PlaneCalibration.point(e.getJSONArray("positionM")),truth),sigma=Math.max(.0001,e.getDouble("sigmaM")),extra=e.getDouble("radiusM")-2.5*sigma,radius=kind.equals("evaluate")?profile.getDouble("multiplier")*sigma+extra:e.getDouble("radiusM");ratios.add(err/sigma);if(err<=radius)covered++;errorSum+=err;radiusSum+=radius;scores.put(WorldFrames.copy(ref).put("errorM",err).put("sigmaM",sigma).put("radiusM",radius).put("acceptedMeasurement",e.getBoolean("accepted")).put("covered",err<=radius));}
        if(kind.equals("fit")){Collections.sort(ratios);int rank=Math.min(refs.length(),(int)Math.ceil((refs.length()+1)*.9));return out.put("multiplier",Math.max(.1,ratios.get(rank-1))).put("rank",rank).put("targetCoverage",.9).put("referenceCount",refs.length()).put("scores",scores).put("qualification","Calibration-only empirical residual quantile; correlated samples, independent physical references required, no probability guarantee or action promotion.");}
        double coverage=covered/(double)refs.length(),meanRadius=radiusSum/refs.length();return out.put("profileId",profile.getString("id")).put("scores",scores).put("metrics",new JSONObject().put("referenceCount",refs.length()).put("coverage",coverage).put("meanErrorM",errorSum/refs.length()).put("meanRadiusM",meanRadius)).put("passed",coverage>=.8&&meanRadius<=.02).put("qualification","Finite same-camera/target reference evaluation; not general metrology or physical-action authority.");
    }
    private static double[] mean(JSONArray rows,int from,int to){double[] out=new double[2];for(int i=from;i<to;i++){var e=rows.getJSONObject(i).getJSONObject("estimate");if(!e.getBoolean("accepted"))throw new IllegalStateException("Start/end window includes unmeasured positions; retain failed recording and acquire a new declared trial");out[0]+=e.getJSONArray("positionM").getDouble(0);out[1]+=e.getJSONArray("positionM").getDouble(1);}out[0]/=to-from;out[1]/=to-from;return out;}
}
